import 'package:figmine/src/codegen/emit/doc_comment.dart';
import 'package:figmine/src/figma/figma_file_meta.dart';

/// Builds the start of every generated library.
abstract final class LibraryHeader {
  /// Returns the doc comment, `library;` and sorted directives.
  static String render(
    FigmaFileMeta meta, {
    List<String> imports = const [],
    List<String> exports = const [],
    List<String> doc = const [],
  }) {
    final version = meta.version.isEmpty ? '' : ', version ${meta.version}';
    final origin =
        'Generated by figmine from the Figma file '
        '"${DocComment.escape(meta.name)}"$version. Do not edit by hand.';
    final buffer = StringBuffer(DocComment.render([origin, ...doc]))
      ..writeln('library;');
    _section(buffer, 'import', imports);
    _section(buffer, 'export', exports);
    return buffer.toString();
  }

  static void _section(StringBuffer buffer, String keyword, List<String> uris) {
    final sorted = [...uris]..sort(_compare);
    var group = -1;
    for (final uri in sorted) {
      if (_rank(uri) != group) buffer.writeln();
      group = _rank(uri);
      buffer.writeln("$keyword '$uri';");
    }
  }

  static int _compare(String a, String b) {
    final byRank = _rank(a).compareTo(_rank(b));
    return byRank == 0 ? a.compareTo(b) : byRank;
  }

  static int _rank(String uri) {
    if (uri.startsWith('dart:')) return 0;
    if (uri.startsWith('package:')) return 1;
    return 2;
  }
}
